<div class="page-heading"><div><p class="context">Exploitation du site</p><h1>Vue d’ensemble</h1><p>Les quais, les camions et les marchandises au même endroit.</p></div><span class="date-label"><?= h(date('d/m/Y')) ?></span></div>
<section class="dock-board"><div class="section-heading"><h2>Situation des quais</h2><a href="/?page=planning">Voir le planning</a></div><div class="dock-grid"><?php foreach($reports->docks(date('Y-m-d')) as $d): ?><article class="dock-bay"><div class="bay-code"><?= h($d['code']) ?></div><div class="bay-door" aria-hidden="true"></div><h3><?= h($d['name']) ?></h3><?= badge($d['live_state']) ?><p><?= h($d['appointments']) ?> rendez-vous aujourd’hui</p></article><?php endforeach; ?></div></section>
<div class="split-layout"><section class="panel"><h2>Votre poste de travail</h2><div class="task-list"><?php foreach(['planning'=>['Organiser les rendez-vous','trace'],'visits'=>['Accueillir un camion','visits'],'receipts'=>['Réceptionner les marchandises','stock'],'stock'=>['Ranger ou transférer un stock','stock'],'orders'=>['Préparer une commande','orders'],'reports'=>['Consulter les indicateurs','reports']] as $p=>[$label,$right])if(Auth::can($user,$right)): ?><a href="<?= h(url(['page'=>$p])) ?>"><?= h($label) ?><span aria-hidden="true">›</span></a><?php endif; ?></div></section><section class="panel"><h2>Activité en cours</h2><?php $open=$db->all("SELECT reference,operation,status FROM truck_visit WHERE status NOT IN ('departed','rejected') ORDER BY id DESC LIMIT 8");if(!$open): ?><p class="empty">Aucun camion sur le site. Les nouvelles arrivées apparaîtront ici.</p><?php else: dataTable(array_map(fn($r)=>['Passage'=>$r['reference'],'Opération'=>$r['operation'],'État'=>Catalog::VALUES[$r['status']]],$open));endif; ?><p class="muted">Le planning s’actualise toutes les 30 secondes. Les opérations validées restent consultables dans l’historique.</p></section></div>
